mapper.select:
SELECT t.*, u.name, u.username FROM base_rbac_user_role t LEFT JOIN base_user u ON t.user_id = u.id WHERE t.deleted = false AND u.deleted = false
AND t.role_id = #{query.roleId}
AND u.name LIKE concat('%', #{query.name}, '%')
AND u.username LIKE concat('%', #{query.username}, '%')
ORDER BY ${sorter}

SELECT count(0) FROM base_rbac_menu WHERE deleted = false AND id IN (
    SELECT menu_id FROM base_rbac_role_menu WHERE deleted = false AND role_id IN (
        SELECT role_id FROM base_rbac_user_role WHERE deleted = false AND user_id = #{userId}
    )
) AND link_url = #{linkUrl}
